import json
import os
import platform
import shutil
import subprocess
import sys
import time

# Try to import psutil for high-accuracy metrics.
# If not available, we fall back to native system commands and APIs.
try:
    import psutil
    HAS_PSUTIL = True
except ImportError:
    HAS_PSUTIL = False


def get_metrics_via_psutil():
    """Gathers system metrics using the psutil library."""
    cpu_pct = psutil.cpu_percent(interval=0.5)
    mem = psutil.virtual_memory()

    # Get disk usage for the root partition (or primary drive on Windows)
    path = "C:\\" if platform.system() == "Windows" else "/"
    disk = psutil.disk_usage(path)

    return {
        "collector_method": "psutil",
        "timestamp": time.time(),
        "system": platform.system(),
        "cpu": {
            "utilization_percent": cpu_pct,
            "cores_logical": psutil.cpu_count(logical=True),
            "cores_physical": psutil.cpu_count(logical=False)
        },
        "memory": {
            "total_bytes": mem.total,
            "available_bytes": mem.available,
            "used_bytes": mem.used,
            "utilization_percent": mem.percent
        },
        "disk": {
            "path": path,
            "total_bytes": disk.total,
            "used_bytes": disk.used,
            "free_bytes": disk.free,
            "utilization_percent": disk.percent
        }
    }


def get_metrics_via_fallback():
    """Gathers system metrics using native standard libraries and shell commands."""
    system = platform.system()
    path = "C:\\" if system == "Windows" else "/"

    metrics = {
        "collector_method": "native_fallback",
        "timestamp": time.time(),
        "system": system,
        "cpu": {
            "utilization_percent": None,
            "cores_logical": os.cpu_count(),
            "cores_physical": None
        },
        "memory": {
            "total_bytes": None,
            "available_bytes": None,
            "used_bytes": None,
            "utilization_percent": None
        },
        "disk": {
            "path": path,
            "total_bytes": None,
            "used_bytes": None,
            "free_bytes": None,
            "utilization_percent": None
        }
    }

    # 1. Disk Space (Cross-platform via shutil)
    try:
        total, used, free = shutil.disk_usage(path)
        metrics["disk"] = {
            "path": path,
            "total_bytes": total,
            "used_bytes": used,
            "free_bytes": free,
            "utilization_percent": round((used / total) * 100, 2) if total else 0.0
        }
    except Exception:
        pass

    # 2. Platform-Specific CPU and Memory Fallbacks
    if system == "Linux":
        # CPU Utilization via /proc/stat
        try:
            def read_proc_stat():
                with open('/proc/stat', 'r') as f:
                    fields = [float(column) for column in f.readline().strip().split()[1:]]
                idle, total = fields[3], sum(fields)
                return idle, total

            idle1, total1 = read_proc_stat()
            time.sleep(0.2)
            idle2, total2 = read_proc_stat()

            idle_delta = idle2 - idle1
            total_delta = total2 - total1
            if total_delta > 0:
                metrics["cpu"]["utilization_percent"] = round((1.0 - idle_delta / total_delta) * 100, 2)
        except Exception:
            # Fallback to load average
            try:
                metrics["cpu"]["utilization_percent"] = round((os.getloadavg()[0] / os.cpu_count()) * 100, 2)
            except Exception:
                pass

        # Memory via /proc/meminfo
        try:
            meminfo = {}
            with open('/proc/meminfo', 'r') as f:
                for line in f:
                    parts = line.split()
                    if len(parts) >= 2:
                        key = parts[0].replace(':', '')
                        meminfo[key] = int(parts[1]) * 1024  # Convert KB to Bytes

            total = meminfo.get('MemTotal', 0)
            # MemAvailable is preferred; fallback to MemFree + Buffers + Cached
            available = meminfo.get('MemAvailable', meminfo.get('MemFree', 0) + meminfo.get('Buffers', 0) + meminfo.get('Cached', 0))
            used = total - available

            metrics["memory"] = {
                "total_bytes": total,
                "available_bytes": available,
                "used_bytes": used,
                "utilization_percent": round((used / total) * 100, 2) if total else 0.0
            }
        except Exception:
            pass

    elif system == "Windows":
        # CPU Utilization via wmic
        try:
            out = subprocess.check_output("wmic cpu get LoadPercentage", shell=True).decode().strip()
            lines = [line.strip() for line in out.split('\n') if line.strip()]
            if len(lines) > 1:
                metrics["cpu"]["utilization_percent"] = float(lines[1])
        except Exception:
            pass

        # Memory via ctypes (GlobalMemoryStatusEx)
        try:
            import ctypes
            class MEMORYSTATUSEX(ctypes.Structure):
                _fields_ = [
                    ('dwLength', ctypes.c_ulong),
                    ('dwMemoryLoad', ctypes.c_ulong),
                    ('ullTotalPhys', ctypes.c_ulonglong),
                    ('ullAvailPhys', ctypes.c_ulonglong),
                    ('ullTotalPageFile', ctypes.c_ulonglong),
                    ('ullAvailPageFile', ctypes.c_ulonglong),
                    ('ullTotalVirtual', ctypes.c_ulonglong),
                    ('ullAvailVirtual', ctypes.c_ulonglong),
                    ('ullAvailExtendedVirtual', ctypes.c_ulonglong),
                ]
            stat = MEMORYSTATUSEX()
            stat.dwLength = ctypes.sizeof(MEMORYSTATUSEX)
            if ctypes.windll.kernel32.GlobalMemoryStatusEx(ctypes.byref(stat)):
                metrics["memory"] = {
                    "total_bytes": stat.ullTotalPhys,
                    "available_bytes": stat.ullAvailPhys,
                    "used_bytes": stat.ullTotalPhys - stat.ullAvailPhys,
                    "utilization_percent": float(stat.dwMemoryLoad)
                }
        except Exception:
            pass

    elif system == "Darwin":  # macOS
        # CPU Utilization via ps
        try:
            out = subprocess.check_output(["ps", "-A", "-o", "%cpu"]).decode()
            lines = out.split('\n')[1:]
            total_cpu = sum(float(x) for x in lines if x.strip())
            metrics["cpu"]["utilization_percent"] = round(total_cpu / os.cpu_count(), 2)
        except Exception:
            try:
                metrics["cpu"]["utilization_percent"] = round((os.getloadavg()[0] / os.cpu_count()) * 100, 2)
            except Exception:
                pass

        # Memory via sysctl and vm_stat
        try:
            total_out = subprocess.check_output(["sysctl", "-n", "hw.memsize"]).decode().strip()
            total = int(total_out)

            vm_out = subprocess.check_output(["vm_stat"]).decode()
            vm_lines = vm_out.split('\n')
            page_size = 4096
            free_pages = 0
            for line in vm_lines:
                if "page size of" in line:
                    page_size = int(line.split()[-2])
                elif "Pages free:" in line:
                    free_pages = int(line.split()[-1].replace('.', ''))

            available = free_pages * page_size
            used = total - available
            metrics["memory"] = {
                "total_bytes": total,
                "available_bytes": available,
                "used_bytes": used,
                "utilization_percent": round((used / total) * 100, 2) if total else 0.0
            }
        except Exception:
            pass

    return metrics


def main():
    if HAS_PSUTIL:
        metrics = get_metrics_via_psutil()
    else:
        metrics = get_metrics_via_fallback()

    # Output the metrics as a beautifully formatted JSON object
    print(json.dumps(metrics, indent=4))


if __name__ == "__main__":
    main()
